function cycles(birth, target){
  function days(a,b){ return Math.round((Date.parse(b)-Date.parse(a))/86400000); }
  var n=days(birth, target);
  function v(p){ return +((Math.sin(2*Math.PI*n/p))*100).toFixed(2); }
  return {days:n, physical:v(23), emotional:v(28), intellectual:v(33)};
}
var EXPORTS={cycles:cycles};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.BiorhythmForgePure = EXPORTS; }
